// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.diimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.common.DefaultDispatcherimport com.roshan.persona.common.IoDispatcherimport com.roshan.persona.connectivity.call.BouncerTtsInterfaceimport com.roshan.persona.connectivity.call.CallEngineimport com.roshan.persona.connectivity.call.CallLogServiceimport com.roshan.persona.connectivity.call.CallServiceimport com.roshan.persona.connectivity.call.SpamDatabaseimport com.roshan.persona.connectivity.call.SpamDetectorEngineimport com.roshan.persona.connectivity.contact.ContactManagerimport com.roshan.persona.connectivity.contact.ContactSearcherimport com.roshan.persona.connectivity.contact.ContactServiceimport com.roshan.persona.connectivity.contact.SimManagerimport com.roshan.persona.connectivity.contact.SimServiceimport com.roshan.persona.connectivity.contact.WritableContactServiceimport com.roshan.persona.connectivity.facade.ConnectivityFacadeimport com.roshan.persona.connectivity.messaging.MessagingAccessibilityBridgeimport com.roshan.persona.connectivity.messaging.NoopMessagingAccessibilityBridgeimport com.roshan.persona.connectivity.messaging.OutboundExecutorimport com.roshan.persona.connectivity.model.ConnectivityConfigimport com.roshan.persona.connectivity.sms.SmartReplyContextimport com.roshan.persona.connectivity.recording.Aes256Encryptorimport com.roshan.persona.connectivity.recording.AudioRecorderimport com.roshan.persona.connectivity.recording.CallRecordingEngineimport com.roshan.persona.connectivity.recording.RecordingStoreimport com.roshan.persona.connectivity.recording.TranscriptionLlmimport com.roshan.persona.connectivity.sms.SmsEngineimport com.roshan.persona.connectivity.sms.SmsHistoryServiceimport com.roshan.persona.connectivity.sms.SmsServiceimport com.roshan.persona.connectivity.sms.SmsTemplateManagerimport com.roshan.persona.connectivity.sms.SmartReplyEngineimport com.roshan.persona.connectivity.sms.SmartReplyLlmimport com.roshan.persona.connectivity.sos.EmergencySOSEngineimport com.roshan.persona.connectivity.sos.LocationProviderimport com.roshan.persona.connectivity.sos.ProactiveCommsEngineimport com.roshan.persona.connectivity.sos.SosTtsSpeakerimport com.roshan.persona.connectivity.skills.NousCallSkillimport com.roshan.persona.connectivity.skills.NousSendSmsSkillimport com.roshan.persona.connectivity.unified.CommsHistoryEngineimport com.roshan.persona.connectivity.unified.LiveTranslationBridgeimport com.roshan.persona.connectivity.unified.MessagingUnificationEngineimport com.roshan.persona.connectivity.unified.NotificationListenerInterfaceimport com.roshan.persona.connectivity.unified.ShareEngineimport com.roshan.persona.connectivity.unified.TranslationServiceimport com.roshan.persona.brain.skill.BrainSkillimport dagger.Bindsimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport kotlinx.coroutines.CoroutineDispatcherimport javax.inject.Singleton/** * NOUS — Connectivity Hilt Module (Module 11 v3 — Phase 1 stub-removal). * * Wires the [ConnectivityFacade] and all 12 v3 engines into the Hilt graph * using **real Android API implementations** — every service is backed by a * real platform API (TelecomManager, SmsManager, ContactsContract, CallLog, * Telephony.Sms, SubscriptionManager, MediaRecorder, LocationManager, * NotificationManager). See [AndroidConnectivityServices] for the full list. * * ## What this module provides * *  - [ConnectivityConfig] — singleton, default config. *  - All service interfaces as **real Android impls** (`Android*Service` / *    `FileRecordingStore` / `InMemorySpamDatabase`) — every impl takes *    `@ApplicationContext context: Context`, queries a real system service, *    and degrades gracefully when the runtime permission is missing. *  - All 12 engines as singletons. *  - [ConnectivityFacade] — singleton, aggregates all engines. *  - [NousCallSkill] + [NousSendSmsSkill] bound via `@Binds @IntoSet`. * * ## Real Android APIs (no stubs, no fakes) * *  | Service | Real API | *  |---------|----------| *  | [CallService] | [android.telecom.TelecomManager] + `Intent.ACTION_CALL` | *  | [CallLogService] | [android.provider.CallLog.Calls] ContentResolver | *  | [SmsService] | [android.telephony.SmsManager] | *  | [SmsHistoryService] | [android.provider.Telephony.Sms] ContentResolver | *  | [WritableContactService] | [android.provider.ContactsContract] | *  | [SimService] | [android.telephony.SubscriptionManager] + [android.telephony.TelephonyManager] | *  | [SpamDatabase] | in-memory ConcurrentHashMap (v1; Room-backed in v2) | *  | [AudioRecorder] | [android.media.MediaRecorder] (MIC source, v1) | *  | [TranscriptionLlm] | null (Brain's LLM handles transcription in v2+) | *  | [RecordingStore] | app-internal storage (`filesDir/recordings/`) | *  | [NotificationListenerInterface] | `Settings.Secure` notification-listener check | *  | [LocationProvider] | [android.location.LocationManager] (no Play Services dep) | *  | [MessagingAccessibilityBridge] | [NoopMessagingAccessibilityBridge] (needs Module 9 NousAccessibilityService) | * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Implementation Plan — Step 11.8</a> */@Module@InstallIn(SingletonComponent::class)object ConnectivityModule {    // ─── Config ───────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideConnectivityConfig(): ConnectivityConfig = ConnectivityConfig()    // ─── Service interfaces (real Android impls) ─────────────────────────    @Provides    @Singleton    fun provideCallService(@ApplicationContext context: Context): CallService =        AndroidCallService(context)    @Provides    @Singleton    fun provideCallLogService(@ApplicationContext context: Context): CallLogService =        AndroidCallLogService(context)    @Provides    @Singleton    fun provideSmsService(@ApplicationContext context: Context): SmsService =        AndroidSmsService(context)    @Provides    @Singleton    fun provideSmsHistoryService(@ApplicationContext context: Context): SmsHistoryService =        AndroidSmsHistoryService(context)    @Provides    @Singleton    fun provideContactService(@ApplicationContext context: Context): WritableContactService =        AndroidContactService(context)    /**     * Bind [ContactService] (read-only interface) to the [AndroidContactService]     * implementation. Consumers that only need to READ contacts use this     * narrower interface (Liskov substitution).     */    @Provides    @Singleton    fun provideReadOnlyContactService(impl: WritableContactService): ContactService = impl    @Provides    @Singleton    fun provideSimService(@ApplicationContext context: Context): SimService =        AndroidSimService(context)    @Provides    @Singleton    fun provideSpamDatabase(): SpamDatabase = InMemorySpamDatabase()    @Provides    @Singleton    fun provideSmartReplyLlm(): SmartReplyLlm? = null  // Module 4 LLM wires real impl    @Provides    @Singleton    fun provideSmartReplyContextProvider(): () -> SmartReplyContext = {        SmartReplyContext(            isDriving = false,            isInMeeting = false,            isSleeping = false,            etaMinutes = null,            meetingEndsAt = null,        )    }    @Provides    @Singleton    fun provideBouncerTtsInterface(): BouncerTtsInterface = BouncerTtsInterface { /* no-op */ }    @Provides    @Singleton    fun provideSmsTtsReader(): com.roshan.persona.connectivity.sms.SmsTtsReader =        com.roshan.persona.connectivity.sms.SmsTtsReader { /* no-op */ }    @Provides    @Singleton    fun provideSmsTemplateManager(): SmsTemplateManager = SmsTemplateManager()    @Provides    @Singleton    fun provideAudioRecorder(@ApplicationContext context: Context): AudioRecorder =        AndroidAudioRecorder(context)    /**     * Transcription LLM is intentionally null in v1.     *     * Strategy §"CallRecordingEngine" — Brain's LLM (Module 4 Whisper.cpp)     * handles transcription in v2+. v1 stores recordings without transcripts     * (the user can still listen to the encrypted audio + delete it).     */    @Provides    @Singleton    fun provideTranscriptionLlm(): TranscriptionLlm? = null    @Provides    @Singleton    fun provideRecordingStore(@ApplicationContext context: Context): RecordingStore =        FileRecordingStore(context)    @Provides    @Singleton    fun provideAes256Encryptor(        @ApplicationContext context: Context,    ): Aes256Encryptor {        // v1: derive a deterministic key from a device-specific secret.        // v2+ (Module 12 Security) replaces this with Android Keystore (hardware-backed).        // The fileWriter writes encrypted bytes to app-internal storage under        // `filesDir/recordings/<recordingId>.enc` — real persistence, not a stub.        val keyBytes = Aes256Encryptor.deriveKey("nous-default-device-secret-v3")        val recordingsDir = java.io.File(context.filesDir, "recordings").apply { mkdirs() }        return Aes256Encryptor(            keyProvider = { keyBytes },            fileWriter = { encrypted, fileName ->                try {                    val file = java.io.File(recordingsDir, fileName)                    file.writeBytes(encrypted)                    file.absolutePath                } catch (t: Throwable) {                    Timber.tag("ConnectivityModule").e("AES file writer failed", t)                    null                }            },        )    }    @Provides    @Singleton    fun provideNotificationListener(        @ApplicationContext context: Context,    ): NotificationListenerInterface = AndroidNotificationListener(context)    /**     * Accessibility bridge for messaging apps (WhatsApp/Telegram auto-send).     *     * Returns [NoopMessagingAccessibilityBridge] until Module 9 ships the     * real `NousAccessibilityService`. The OutboundExecutor falls back to     * opening the chat with a pre-filled message — the user taps Send.     */    @Provides    @Singleton    fun provideAccessibilityBridge(): MessagingAccessibilityBridge =        NoopMessagingAccessibilityBridge()    @Provides    @Singleton    fun provideLocationProvider(@ApplicationContext context: Context): LocationProvider =        AndroidLocationProvider(context)    @Provides    @Singleton    fun provideSosTtsSpeaker(): SosTtsSpeaker = object : SosTtsSpeaker {        override fun speakCountdown(secondsRemaining: Int) { /* no-op */ }        override fun speakDispatched() { /* no-op */ }    }    @Provides    @Singleton    fun provideTranslationService(): TranslationService? = null  // Module 4+5 wires real impl    @Provides    @Singleton    fun provideTranslationDisplayCallback(): (String) -> Unit = { /* no-op */ }    @Provides    @Singleton    fun provideContactChecker(        contactService: ContactService,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): (String) -> Boolean = { phone ->        // Synchronous check — used by SpamDetectorEngine for contact-list lookup.        // getAllContacts() is suspend — wrap in runBlocking since the spam        // detector's signature requires a synchronous lambda. This is called        // on the IO dispatcher (passed in above) so it never blocks the main        // thread when invoked from the engine.        kotlinx.coroutines.runBlocking {            try {                contactService.getAllContacts().any { contact ->                    contact.phoneNumbers.any {                        it.filter { c -> c.isDigit() } == phone.filter { c -> c.isDigit() }                    }                }            } catch (t: Throwable) {                // Any error reading contacts → treat as "not a contact" (caller will                // be flagged as potential spam if also in spam DB).                false            }        }    }    // ─── Engines ──────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideSpamDetectorEngine(        spamDb: SpamDatabase,        contactChecker: @JvmSuppressWildcards (String) -> Boolean,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): SpamDetectorEngine = SpamDetectorEngine(        spamDb = spamDb,        contactChecker = contactChecker,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideCallEngine(        callService: CallService,        spamDetector: SpamDetectorEngine,        contactSearcher: ContactSearcher,        bouncerTts: BouncerTtsInterface,        config: ConnectivityConfig,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): CallEngine = CallEngine(        callService = callService,        spamDetector = spamDetector,        contactSearcher = contactSearcher,        bouncerTts = bouncerTts,        emergencyNumbers = config.emergencyNumbers,        bouncerMode = config.bouncerMode,        activeBouncerEnabled = config.activeBouncerEnabled,        bouncerGreeting = config.bouncerGreeting,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideContactSearcher(        contactService: ContactService,        config: ConnectivityConfig,    ): ContactSearcher = ContactSearcher(        contactService = contactService,        maxFuzzyDistance = config.maxFuzzyDistance,        maxResults = config.maxSearchResults,    )    @Provides    @Singleton    fun provideContactManager(        contactService: WritableContactService,    ): ContactManager = ContactManager(contactService)    @Provides    @Singleton    fun provideSimManager(        simService: SimService,    ): SimManager = SimManager(simService)    @Provides    @Singleton    fun provideSmartReplyEngine(        llm: SmartReplyLlm?,        contextProvider: () -> SmartReplyContext,        @DefaultDispatcher dispatcher: CoroutineDispatcher,    ): SmartReplyEngine = SmartReplyEngine(        llm = llm,        contextProvider = contextProvider,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideSmsEngine(        smsService: SmsService,        smsHistory: SmsHistoryService,        smartReplyEngine: SmartReplyEngine,        ttsReader: com.roshan.persona.connectivity.sms.SmsTtsReader,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): SmsEngine = SmsEngine(        smsService = smsService,        smsHistory = smsHistory,        smartReplyEngine = smartReplyEngine,        ttsReader = ttsReader,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideOutboundExecutor(        @ApplicationContext context: Context,        accessibilityBridge: MessagingAccessibilityBridge,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): OutboundExecutor = OutboundExecutor(        context = context,        accessibilityBridge = accessibilityBridge,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideMessagingUnificationEngine(        notificationListener: NotificationListenerInterface,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): MessagingUnificationEngine = MessagingUnificationEngine(        notificationListener = notificationListener,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideCommsHistoryEngine(        callLogService: CallLogService,        smsHistoryService: SmsHistoryService,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): CommsHistoryEngine = CommsHistoryEngine(        callLogService = callLogService,        smsHistoryService = smsHistoryService,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideShareEngine(        @ApplicationContext context: Context,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ShareEngine = ShareEngine(        context = context,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideLiveTranslationBridge(        translationService: TranslationService?,        displayCallback: (String) -> Unit,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): LiveTranslationBridge = LiveTranslationBridge(        translationService = translationService,        displayCallback = displayCallback,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideCallRecordingEngine(        recorder: AudioRecorder,        transcriber: TranscriptionLlm?,        store: RecordingStore,        encryptor: Aes256Encryptor,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): CallRecordingEngine = CallRecordingEngine(        recorder = recorder,        transcriber = transcriber,        store = store,        encryptor = encryptor,        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideEmergencySosEngine(        callEngine: CallEngine,        smsService: SmsService,        locationProvider: LocationProvider,        ttsSpeaker: SosTtsSpeaker,        config: ConnectivityConfig,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): EmergencySOSEngine = EmergencySOSEngine(        callEngine = callEngine,        smsService = smsService,        locationProvider = locationProvider,        ttsSpeaker = ttsSpeaker,        countdownSeconds = config.sosCountdownSeconds,        locationUpdateSeconds = config.sosLocationUpdateSeconds,        locationDurationMinutes = config.sosLocationDurationMinutes,        emergencyNumber = config.emergencyNumbers.first(),        dispatcher = dispatcher,    )    @Provides    @Singleton    fun provideProactiveCommsEngine(        callLogService: CallLogService,        smsHistoryService: SmsHistoryService,        config: ConnectivityConfig,        @IoDispatcher dispatcher: CoroutineDispatcher,    ): ProactiveCommsEngine = ProactiveCommsEngine(        callLogService = callLogService,        smsHistoryService = smsHistoryService,        dispatcher = dispatcher,        neglectThresholdDays = config.neglectAlertThresholdDays,    )    // ─── Facade ───────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideConnectivityFacade(        callEngine: CallEngine,        spamDetector: SpamDetectorEngine,        smsEngine: SmsEngine,        smsTemplateManager: SmsTemplateManager,        contactSearcher: ContactSearcher,        contactManager: ContactManager,        simManager: SimManager,        outboundExecutor: OutboundExecutor,        messagingUnificationEngine: MessagingUnificationEngine,        commsHistoryEngine: CommsHistoryEngine,        shareEngine: ShareEngine,        liveTranslationBridge: LiveTranslationBridge,        callRecordingEngine: CallRecordingEngine,        emergencySosEngine: EmergencySOSEngine,        proactiveCommsEngine: ProactiveCommsEngine,    ): ConnectivityFacade = ConnectivityFacade(        callEngine = callEngine,        spamDetector = spamDetector,        smsEngine = smsEngine,        smsTemplateManager = smsTemplateManager,        contactSearcher = contactSearcher,        contactManager = contactManager,        simManager = simManager,        outboundExecutor = outboundExecutor,        messagingUnificationEngine = messagingUnificationEngine,        commsHistoryEngine = commsHistoryEngine,        shareEngine = shareEngine,        liveTranslationBridge = liveTranslationBridge,        callRecordingEngine = callRecordingEngine,        emergencySosEngine = emergencySosEngine,        proactiveCommsEngine = proactiveCommsEngine,    )}// ═══════════════════════════════════════════════════════════════════════════// Brain Skill multibinding module// ═══════════════════════════════════════════════════════════════════════════/** * Binds [NousCallSkill] + [NousSendSmsSkill] into the Brain's [BrainSkill] * multibinding via `@Binds @IntoSet`. The SkillRouter will discover them * alongside Brain's built-in skills. */@Module@InstallIn(SingletonComponent::class)abstract class ConnectivitySkillsModule {    @Binds @IntoSet    abstract fun bindNousCallSkill(impl: NousCallSkill): BrainSkill    @Binds @IntoSet    abstract fun bindNousSendSmsSkill(impl: NousSendSmsSkill): BrainSkill}